public class NonBlockingNotificationDispatcher {
    private Selector selector;
    private ExecutorService workerPool;

    public void initialize() throws IOException {
        selector = Selector.open();
        workerPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void registerChannel(SocketChannel channel, NotificationPayload payload) throws IOException {
        channel.configureBlocking(false);
        SelectionKey key = channel.register(selector, SelectionKey.OP_WRITE, payload);
    }

    public void processIoEvents() {
        try {
            if (selector.selectNow() > 0) {
                Iterator<SelectionKey> iterator = selector.selectedKeys().iterator();
                while (iterator.hasNext()) {
                    SelectionKey key = iterator.next();
                    iterator.remove();
                    if (key.isWritable()) {
                        handleWrite(key);
                    }
                }
            }
        } catch (IOException e) {
            handleChannelException(e);
        }
    }

    private void handleWrite(SelectionKey key) {
        SocketChannel channel = (SocketChannel) key.channel();
        NotificationPayload payload = (NotificationPayload) key.attachment();
        try {
            ByteBuffer buffer = ByteBuffer.wrap(payload.toJsonBytes());
            channel.write(buffer);
            if (!buffer.hasRemaining()) {
                key.cancel();
                channel.close();
            }
        } catch (IOException e) {
            // Isolate exception, route to retry queue or DLQ
            key.cancel();
            try { channel.close(); } catch (IOException ignored) {}
        }
    }

    private void handleChannelException(IOException e) {
        // Log and emit metrics for selector failures
    }
}
